// Request georeferenced NAIP images on the same Web Mercator grid as the current basemap.
// Source is part of the cache key so changing imagery never reuses another year's tiles.
function imageryTileUrl(source,z,x,y){
  if(source==='current')return `https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryOnly/MapServer/tile/${z}/${y}/${x}`;
  const half=20037508.342789244,span=2*half/2**z;
  const bbox=[-half+x*span,half-(y+1)*span,-half+(x+1)*span,half-y*span];
  const base=source==='latestnaip'?'https://apps.geo.fpac.usda.gov/geo-imagery/rest/services/naip/conus_naip/ImageServer':`https://gis.wildlife.ca.gov/images/rest/services/Base_Remote_Sensing/NAIP_${source}/ImageServer`;
  const params=new URLSearchParams({f:'image',bbox:bbox.join(','),bboxSR:'3857',imageSR:'3857',size:'256,256',format:'png32',interpolation:'RSP_BilinearInterpolation'});
  return base+'/exportImage?'+params;
}
function updateImageryStatus(){
  const enabled=$('aerial').checked,source=$('imageryyear').value;
  $('imageryyear').disabled=!enabled;
  $('attribution').style.display=enabled?'block':'none';
  $('attribution').textContent=source==='current'?'Imagery: USGS The National Map / USDA · current basemap':source==='latestnaip'?'Imagery: Latest NAIP · USDA':`Imagery: NAIP ${source} · USDA / CDFW`;
  if(!enabled){$('imagerystatus').textContent='';$('imageryretry').hidden=true;return}
  const images=[...tileCache.values()],failed=images.filter(img=>img.dataset.state==='error').length,pending=images.filter(img=>img.dataset.state==='loading').length;
  $('imagerystatus').textContent=failed?'Some imagery could not load. Try another year or use Retry.':pending?'Loading imagery…':'';
  $('imageryretry').hidden=!enabled||!failed;
}
function resetImagery(){for(const img of tileCache.values()){img.onload=null;img.onerror=null;img.remove()}tileCache.clear();draw()}
function updateTiles(){
  let layer=$('tiles');if(!$('aerial').checked){layer.style.display='none';updateImageryStatus();return}layer.style.display='block';
  const source=$('imageryyear').value,half=20037508.342789244,w=$('map').clientWidth,h=$('map').clientHeight;
  let z=Math.max(0,Math.min(18,Math.round(Math.log2(156543.03392804097*view.scale))));
  let resolution=156543.03392804097/2**z,span=256*resolution,size=span*view.scale;
  let left=(-view.x/view.scale+half),right=((w-view.x)/view.scale+half),top=(half-view.y/view.scale),bottom=(half-(view.y-h)/view.scale);
  let x0=Math.max(0,Math.floor(left/span)),x1=Math.min(2**z-1,Math.floor(right/span)),y0=Math.max(0,Math.floor(top/span)),y1=Math.min(2**z-1,Math.floor(bottom/span));
  let wanted=new Set();
  for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){
    let key=`${source}/${z}/${y}/${x}`;wanted.add(key);let img=tileCache.get(key);
    if(!img){img=new Image();img.alt='';img.loading='eager';img.dataset.state='loading';
      img.onload=()=>{if(tileCache.get(key)!==img)return;img.dataset.state='loaded';updateImageryStatus()};
      img.onerror=()=>{if(tileCache.get(key)!==img)return;img.dataset.state='error';img.style.visibility='hidden';updateImageryStatus()};
      tileCache.set(key,img);layer.append(img);img.src=imageryTileUrl(source,z,x,y);
    }
    img.style.left=(view.x+(-half+x*span)*view.scale)+'px';img.style.top=(view.y-(half-y*span)*view.scale)+'px';img.style.width=(size+.5)+'px';img.style.height=(size+.5)+'px';
  }
  for(const [key,img] of tileCache)if(!wanted.has(key)){img.onload=null;img.onerror=null;img.remove();tileCache.delete(key)}
  updateImageryStatus();
}
